record.field:
BASE_URL = "https://staging.channex.io/api/v1"
if not env['ir.config_parameter'].get_str('booking_channex.x_channex_api_key'): raise UserError("Cannot communicate with Channex, API key is missing in the settings.")
try:
    method, endpoint = env.context.get('method'), env.context.get('endpoint')
    if not method or method not in ["GET", "POST", "PUT", "DELETE"]: raise UserError("Http request to channex cannot be sent because method is invalid (not GET, POST, PUT or DELETE)")
    if not endpoint: raise UserError("Http request to channex cannot be sent because endpoint is empty")
    res = requests.request(
        method=method,
        url=f"{BASE_URL}/{endpoint}",
        data=json.dumps(env.context.get('payload', {})),
        timeout=20, headers={
            'Content-Type': 'application/json',
            'user-api-key': env['ir.config_parameter'].get_str('booking_channex.x_channex_api_key')
        }
    )
    res.raise_for_status()
    response = request.make_json_response(res.json(), status=200)
except Exception as e:
    if res.status_code < 300 or (method in ["DELETE", "PUT"] and res.status_code == 404):
        response = request.make_json_response(res.json(), status=200)
    else:
        raise UserError(f"Channex API error: {str(e)}\n\nFailed with the payload:\n{str(env.context.get('payload', {}))}")

local_id = env.context.get('local_id')
if not local_id or not env.context.get('model_type'):
    raise UserError("Could not get the mapping to channex because the searched record or type is not mentionned.")
mapping = env['x_channex_mapping'].search([
    ('x_model_type', '=', env.context.get('model_type')),
    ('x_local_id', '=', local_id)
], limit=1)
if not mapping:
    mapping = env['x_channex_mapping'].create({
        "x_model_type": env.context.get('model_type'),
        "x_local_id": local_id,
    })
action = mapping

#Récupérer la demande de booking
event = payload.get('event')
payload_infos = payload.get('payload', {})
env.ref('booking_channex.requests_to_channex').with_context(
    method="POST", endpoint="booking_revisions/%s/ack" % payload_infos.get('booking_revision_id', '')
).run()#Whether valid or not, it should be acknowledged.
if event == 'booking_new':
    full_booking = env.ref('booking_channex.requests_to_channex').with_context(
        method="GET", endpoint="bookings/%s" % payload_infos.get('booking_id', '')
    ).run().json.get('data', {}).get('attributes', {})

    #To remove after development, display the booking received to have it easier to debug
    records.env.ref('booking_channex.webhook_get_booking_create_change_or_delete').message_post(body=str(full_booking))

    customer = full_booking.get('customer', False)
    if customer:
        partner = env['res.partner']._retrieve_partner(name=customer.get('name', ''), phone=customer.get('phone', False), email=customer.get('mail', ''))
        if not partner:
            partner = env['res.partner']._retrieve_partner(name=customer.get('name', '') + ' ' + customer.get('surname', ''), phone=customer.get('phone', False), email=customer.get('mail', ''))
        if not partner:
            country = env['res.country'].search([('code', '=', customer.get('country', '').lower())]) if customer.get('country', False) else env['res.country']
            state = env['res.country.state'].search(
                [('country_id', '=', country.id), ('code', '=', customer.get('state', ''))], limit=1,
            ) if customer.get('state', '') and country else env['res.country.state']
            partner = env['res.partner'].create({
                'name': customer.get('name', '') + ' ' + customer.get('surname', ''), 'email': customer.get('mail', ''), 'phone': customer.get('phone', False),
                'state_id': state.id, 'country_id': country.id, 'zip': customer.get('zip', False), 'city': customer.get('city', ''), 'street': customer.get('address', ''),
            })
    else:
        partner = env['res.partner'].create({'name': payload_infos.get('customer_name', 'channex partner')})
    currency_id = env['res.currency'].with_context(active_test=False).search([('name', '=', full_booking.get('currency', False))], limit=1)
    if not currency_id: raise UserError(_('Could not find currency %s', currency))
    so = env['sale.order'].create({
        'partner_id': partner.id, 'is_rental_order': True, 'currency_id': currency_id.id
    })
    for room in full_booking.get('rooms', []):
        room_mapping = env['x_channex_mapping'].search(
            [("x_model_type", "=", "room_type"), ('x_remote_id', '=', room.get('room_type_id', ''))], limit=1
        )
        env['sale.order.line'].create({
            'product_id': env['product.product'].browse(room_mapping.x_local_id).id,
            'is_rental': True,
            'order_id': so.id,
            'price_unit': room.get('amount', 0),
            'currency_id': currency_id.id,
        })
        #if (guests := room.get('guests', [])):
        #    env['sale.order.line'].create({
        #        'display_type': 'line_note',
        #        'order_id': so.id,
        #        'name': "Guests: " + "\n".join(guest.get('name', '') + ' ' + guest.get('surname', '') for guest in guests)
        #            + "\n" + #occupancy and days
        #    })
    so['rental_start_date'] = (full_booking.get('arrival_date', '') + ' ' + full_booking.get('arrival_hour', '')).strip()
    so['rental_return_date'] = full_booking.get('departure_date')
    # assert float_compare(so['total_amount'], payload_infos.get('amount'), precision_digits=2) == 0
    env["x_channex_mapping"].create({
        "x_model_type": "booking",
        "x_local_id": so.id,
        "x_remote_id": payload_infos.get('booking_id', ''),
    })
    try:
        so.action_confirm()
    except Exception as exc:
        env['mail.activity'].create({
            'res_model_id': env['ir.model']._get_id('sale.order'),
            'res_id': so.id,
            'activity_type_id': env.ref('mail.mail_activity_data_todo').id,
            'summary': 'Confirm Order',
            'date_deadline': datetime.datetime.today(),
        })
elif booking_id := payload_infos.get('booking_id'):
    mapped_so = env["x_channex_mapping"].search([
        ("x_model_type", "=", "booking"),
        ("x_remote_id", "=", booking_id),
    ], limit=1)
    if event == 'booking_modification':
        pass #Here we should modify the booking, can we do that extensively and automatically ? or should we simply create a task to
        #take into account new reservation (could create overlapping issues later)
    elif event == 'booking_cancellation':
        env['sale.order'].browse(mapped_so.x_local_id).action_cancel()

