for endpoint in ('restrictions', 'availability'):
    if payloads[endpoint]:
        env.ref('booking_channex.requests_to_channex').with_context(method='POST', endpoint=endpoint, payload={'values': payloads[endpoint]}).run()

model.env['ir.cron']._commit_progress(processed=1, remaining=0, deactivate=True)
