                }
            }).run()
            remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
            if not remote_id:
                raise UserError("Invalid response from Channex for the creation of property corresponding to company with id %s" % str(property.id))
            property_mapping.write({'x_remote_id': remote_id})

property_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'property'),('x_local_id', 'in', records.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
for property in records:
    if remote_id := property_mappings_dict.get(property.id):
        env.ref('booking_channex.requests_to_channex').with_context(method="PUT", endpoint="properties/%s" % remote_id, payload={
