                "address": property.street or '',
                "timezone": property.tz or '',
                "website": property.website or '',
            }
        }).run()

if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
    room_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'room_type'),('x_local_id', 'in', records.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
    for room in records:
        if property_mapping := env['x_channex_mapping'].search([('x_model_type', '=', 'property'), ('x_local_id', '=', room.company_id.id or env.company.id), ('x_remote_id', '!=', False)], limit=1):
            mapped_product = env["x_channex_mapping"].search([("x_model_type", "=", "room_type"), ("x_local_id", "=", room.id)], limit=1)
            guests_attribute_value = room.product_template_attribute_value_ids.filtered(lambda a: a.product_attribute_value_id.attribute_id.x_accommodation_characteristic in ['guest']).mapped('product_attribute_value_id')
            room_can_be_on_channex = (len(guests_attribute_value) == 1 and room.x_is_a_room_offer and room.product_tmpl_id.x_has_rates_attribute and room.active)
            if room_can_be_on_channex and mapped_product: #Update
                if remote_id := room_mappings_dict.get(room.id):
                    res = env.ref('booking_channex.requests_to_channex').with_context(method="PUT", endpoint="room_types/%s" % remote_id, payload={
                        "room_type": {
                            "title": room.display_name,
                            "count_of_rooms": room.x_resources_amount or 1,
                            "occ_adults": guests_attribute_value.x_adults, "occ_children": guests_attribute_value.x_children, "occ_infants": guests_attribute_value.x_infants,
                            "default_occupancy": (guests_attribute_value.x_adults + guests_attribute_value.x_children + guests_attribute_value.x_infants) or 1
                        }
                    }).run()
                    if res.json.get('errors', {}).get('code', "") == "resource_not_found":
                        action = {
                            'type': 'ir.actions.client',
                            'tag': 'display_notification',
                            'params': {'message': 'The product could not be updated on channex, as it cannot be found.', 'type': 'warning', 'sticky': False}
                        }
            elif room_can_be_on_channex and not mapped_product: #Create
                room_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="room_type", local_id=room.id).run()
                data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint="room_types", payload={
                    "room_type": {
                        "property_id": property_mapping.x_remote_id,
                        "title": room.display_name,
                        "count_of_rooms": room.x_resources_amount or 1,
                        "occ_adults": guests_attribute_value.x_adults, "occ_children": guests_attribute_value.x_children, "occ_infants": guests_attribute_value.x_infants,
                        "default_occupancy": (guests_attribute_value.x_adults + guests_attribute_value.x_children + guests_attribute_value.x_infants) or 1
                    }
                }).run()
                remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
                if not remote_id: raise UserError("Invalid response from Channex for the creation of room corresponding to product variant with id %s" % str(room.id))
                room_mapping.write({'x_remote_id': remote_id})
            elif not room_can_be_on_channex and mapped_product: #Delete
                env.ref('booking_channex.delete_room_on_channex').with_context(active_ids=[room.id], active_model="product.product").run()

if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
    property_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'property')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
    room_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'room_type')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
    rate_plans_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'rate_plan')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
    new_mappings = records.env['x_channex_mapping'].create([{'x_model_type': 'rate_plan', 'x_local_id': rid} for rid in records.ids])
    for property_id in property_mappings_dict.keys():
        property_remote_id = property_mappings_dict.get(property_id)
        if not property_remote_id:    continue
        rate_plans = records.filtered(lambda r: r.x_variant_id.company_id.id == property_id) if (env['res.company'].search_count([]) > 1) else records
        for rp in rate_plans:
            room_remote_id = room_mappings_dict.get(rp.x_variant_id.id)
            if not room_remote_id: continue
            if rate_plans_mappings_dict.get(rp.id): continue
            data = env.ref('booking_channex.requests_to_channex').with_context(
                method="POST", endpoint="rate_plans", payload={
                    "rate_plan": {
                        "property_id": property_remote_id,
                        "title": rp.x_name,
                        "room_type_id": room_remote_id,
                        "currency": rp.x_pricelist_id.currency_id.name,
                        "options": [{
                            "occupancy": rp.x_total_inventory or 1,
                            "is_primary": True,
                            "rate": int(rp.x_variant_id.lst_price*100),
                        }]
                    }
                }
            ).run()
            remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
            if not remote_id: raise UserError("Invalid response from Channex: " + data.json.get('errors', {}).get('title', ''))
            new_mappings.filtered(lambda m: m.x_local_id == rp.id).write({'x_remote_id': remote_id})

mappings = records.env['x_channex_mapping'].search([('x_model_type', '=', 'rate_plan'), ('x_local_id', 'in', records.ids), ('x_remote_id', '!=', False)])
for mapping in mappings:
    env.ref('booking_channex.requests_to_channex').with_context(
        method="DELETE", endpoint="rate_plans/%s" % mapping.x_remote_id
    ).run()
mappings.unlink()

rate_plan_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'rate_plan'),('x_local_id', 'in', records.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
for rate_plan in records:
    if remote_id := rate_plan_mappings_dict.get(rate_plan.id):
        env.ref('booking_channex.requests_to_channex').with_context(method="PUT", endpoint="rate_plans/%s" % remote_id, payload={
            "rate_plan": {
                "title": rate_plan.x_name,
            }
        }).run()

def construct_availability_payload(property_id, room_type_id, records, ota_buffer):
    room_payload = []

    if not records:
        return room_payload

    current_start = current_end = records[0].x_date
    current_qty = records[0].x_available

    for rec in records[1:]:

        if rec.x_available != current_qty:
            room_payload.append({
                'property_id': property_id,
                'room_type_id': room_type_id,
                'date_from': current_start.strftime('%Y-%m-%d'),
                'date_to': current_end.strftime('%Y-%m-%d'),
                'availability': max(0, current_qty - ota_buffer),
            })

            current_start = current_end = rec.x_date
            current_qty = rec.x_available
        else:
            current_end = rec.x_date

    room_payload.append({
        'property_id': property_id,
        'room_type_id': room_type_id,
        'date_from': current_start.strftime('%Y-%m-%d'),
        'date_to': current_end.strftime('%Y-%m-%d'),
        'availability': max(0, current_qty - ota_buffer),
    })

    return room_payload

payload_values = []
property_remote_id = env.context.get("property_remote_id")
room_type_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'room_type')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
for record in records:
    room_type_remote_id = room_type_mappings_dict.get(record.id)
    if not room_type_remote_id:
        continue
    availability_records = env['x_availability'].search(
        [('x_stay_offer_id', '=', record.product_tmpl_id.id)],
        order='x_date'
    )
    payload_values.extend(construct_availability_payload(property_remote_id, room_type_remote_id, availability_records, record.product_tmpl_id.x_ota_buffer))
action = payload_values

def create_on_channex(endpoint, payload, mapping, error_msg):
    try:
        data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint=endpoint, payload=payload).run()
        remote_id = data.json.get('data', {}).get('attributes', {}).get('id')

        if not remote_id:
            raise UserError(f"{error_msg}: Invalid response from Channex")

        mapping.write({'x_remote_id': remote_id})

    except Exception as e:
        raise UserError(f"{error_msg}: {str(e)}")

if not env['ir.config_parameter'].get_str('booking_channex.x_channex_api_key'):
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'message': 'No Channex sync possible without API key.',
            'type': 'warning',
            'sticky': False,
            'next': {
                'type': 'ir.actions.client',
                'tag': 'soft_reload',
            },
        }
    }
else:
    # webhook
    #ERROR if localhost is used as an url, we cannot test it if we are in local
    resp = env.ref('booking_channex.requests_to_channex').with_context(method="GET", endpoint="webhooks").run()
    data = resp.json

    channex_webhooks = data.get('data', [])
    odoo_webhook = env.ref('booking_channex.webhook_get_booking_create_change_or_delete')
    existing_webhook = False
    for w in channex_webhooks:
        if w.get('attributes', {}).get('callback_url') == odoo_webhook.url:
            existing_webhook = w
            break
    webhook_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="webhook", local_id=odoo_webhook.id).run()

    if existing_webhook:
        webhook_mapping.write({
            'x_remote_id': existing_webhook.get('attributes', {}).get('id')
        })
    else:
        payload = {
            "webhook": {
                "callback_url": odoo_webhook.url,
                "event_mask": "booking_new;booking_modification;booking_cancellation",
                "request_params": {},
                "headers": {},
                "is_active": True,
                "is_global": True,
                "send_data": True
            }
        }
        create_on_channex(
            'webhooks',
            payload,
            webhook_mapping,
            "Error creating webhook"
        )

    # GROUP (x_channex_group -> Channex Group)
    is_db_multi_company = (env['res.company'].search_count([]) > 1)
    groups = env['x_channex_group'].search([])
    if not groups or not any(groups.mapped('x_company_ids')):
        groups += (env['x_channex_group'].create({'x_name': env.company.name, 'x_company_ids': [env.company.id]}))
    for group in groups:
        group_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="group", local_id=group.id).run()
        if not group_mapping.x_remote_id:
            payload = {
                "group": {
                    "title": group.x_name
                }
            }
            create_on_channex(
                "groups",
                payload,
                group_mapping,
                "Error creating group"
            )
        # PROPERTIES (Companies -> Properties)
        for property in group.x_company_ids:
            property_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="property", local_id=property.id).run()
            if not property_mapping.x_remote_id:
                payload = {
                    "property": {  # If possible add logo, longitude, latitude
                        "title": property.name,
                        "currency": property.currency_id.name,
                        "email": property.email or '',
                        "phone": property.phone or '',
                        "group_id": group_mapping.x_remote_id,
                        "property_type": "hotel",  # Should be adapted based on the industry we use
                        "zip_code": property.zip or '',
                        "country": property.country_id.code or '',
                        "state": property.state_id.name or '',
                        "city": property.city or '',
                        "address": property.street or '',
                        "timezone": property.tz or '',
                        "website": property.website or '',
                    }
                }
                create_on_channex(
                    "properties",
                    payload,
                    property_mapping,
                    "Error creating property"
                )

    property_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'property')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))

    # ROOM TYPES (Product Variants → Room Types)
    for property_id in property_mappings_dict.keys():
        property_remote_id = property_mappings_dict.get(property_id)
        if not property_remote_id:    continue
        property_rooms = env['product.product'].search([('x_is_a_room_offer', '=', True), ('active', '=', True)])
        property_rooms = property_rooms.filtered(lambda r: r.product_tmpl_id.x_has_rates_attribute)
        if is_db_multi_company:
            property_rooms = property_rooms.filtered(lambda r: r.company_id.id == property_id)
        for room in property_rooms:
            guests_attribute_value = room.product_template_attribute_value_ids.filtered(lambda a: a.product_attribute_value_id.attribute_id.x_accommodation_characteristic in ['guest']).mapped('product_attribute_value_id')
            if len(guests_attribute_value) != 1:
                continue
            room_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="room_type", local_id=room.id).run()
            if not room_mapping.x_remote_id:
                payload = {
                    "room_type": {
                        "property_id": property_remote_id,
                        "title": room.display_name,
                        "count_of_rooms": room.x_resources_amount or 1,
                        "occ_adults": guests_attribute_value.x_adults, "occ_children": guests_attribute_value.x_children, "occ_infants": guests_attribute_value.x_infants,
                        "default_occupancy": (guests_attribute_value.x_adults + guests_attribute_value.x_children + guests_attribute_value.x_infants) or 1
                    }
                }
                create_on_channex(
                    "room_types",
                    payload,
                    room_mapping,
                    "Error creating room type"
                )

    room_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'room_type')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))

    # RATE PLANS (X Rate Plan → Channex Rate Plan)
    for property_id in property_mappings_dict.keys():
        property_remote_id = property_mappings_dict.get(property_id)
        if not property_remote_id:    continue
        rate_plans = env['x_rate_plan'].search([('x_variant_id', '!=', False), ('x_pricelist_id', '!=', False)])
        for rp in rate_plans:
            room_remote_id = room_mappings_dict.get(rp.x_variant_id.id)
            if not room_remote_id:    continue
            rate_plan_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="rate_plan", local_id=rp.id).run()
            if not rate_plan_mapping.x_remote_id:
                payload = {
                    "rate_plan": {
                        "title": rp.x_name,
                        "property_id": property_remote_id,
                        "room_type_id": room_remote_id,
                        "currency": rp.x_pricelist_id.currency_id.name,
                        "options": [{
                            "occupancy": rp.x_total_inventory or 1,
                            "is_primary": True,
                            "rate": int(rp.x_variant_id.lst_price*100),  # Maybe not the value we want to set, could be changed
                        }],
                    }
                }
                create_on_channex(
                    "rate_plans",
                    payload,
                    rate_plan_mapping,
                    "Error creating rate plan"
                )
    env['ir.config_parameter'].set_bool('booking_channex.synced_with_channex', True)
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'message': 'Data sync non-ARIs with Channex completed successfully.',
            'type': 'success',
            'sticky': False,
            'next': {
                'type': 'ir.actions.client',
                'tag': 'soft_reload',
            },
        }
    }

# availability (X Availability → Channex Availability)

